function currentGroup(){return M.groupBlocks?.[selectedGroupIndex]||null;}
function groupNameTaken(name,except=-1){return M.groupBlocks.some((g,i)=>i!==except&&g.name.toLowerCase()===name.toLowerCase());}
function renderGroupBlock(){
 const host=$('groupBlockPanel');if(!host)return;
 const groups=M.groupBlocks||[];selectedGroupIndex=Math.max(0,Math.min(selectedGroupIndex,groups.length-1));
 const group=currentGroup();
 let html=`<h4>GROUP BLOCK (${groups.length})</h4><p class="status">Kéo Block từ Skeleton vào biến thể đang chọn. Mỗi Block chỉ thuộc một biến thể của một Group; block nền nằm ngoài nhóm.</p>
 <div class="row"><label>Group</label><select id="groupChoose" onchange="selectedGroupIndex=+this.value;renderGroupBlock()">${groups.map((g,i)=>`<option value="${i}" ${i===selectedGroupIndex?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div>
 <div class="row"><label>Tên group</label><input id="groupNameInput" value="${esc(group?.name||'')}" placeholder="Weapon / Outfit"></div>
 <div class="group-actions"><button onclick="addGroupBlock()">＋ Group</button><button ${group?'':'disabled'} onclick="renameGroupBlock()">✎ Đổi tên</button><button ${group?'':'disabled'} onclick="removeGroupBlock()">✕ Xoá group</button></div>`;
 if(group){
  const current=group.variants.find(v=>v.name===group.defaultVariant)||null;
  html+=`<div class="row"><label>Biến thể</label><select id="groupVariantChoose" onchange="selectGroupBlockVariant(this.value)"><option value="" ${current?'':'selected'}>None — không hiện block của group</option>${group.variants.map(v=>`<option value="${esc(v.name)}" ${current===v?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>
   <div class="row"><label>Tên bộ</label><input id="groupVariantInput" value="${esc(current?.name||'')}" placeholder="Dagger / Sword / Armor"></div>
   <div class="group-actions"><button onclick="addGroupBlockVariant()">＋ Biến thể</button><button ${current?'':'disabled'} onclick="renameGroupBlockVariant()">✎ Đổi tên</button><button ${current?'':'disabled'} onclick="removeGroupBlockVariant()">✕ Xoá biến thể</button></div>
   <div class="group-drop" ondragover="groupDragOver(event)" ondragleave="groupDragLeave(event)" ondrop="groupDropBlock(event)">Thả Block từ tab Skeleton vào đây${current?' — '+esc(current.name):' (chọn biến thể trước)'}</div>
   <div class="status">${current?'Block trong '+esc(current.name):'None đang được chọn — tất cả Block thuộc group này bị ẩn'}:</div>
   ${(current?.blockIds||[]).map(id=>{const k=M.blocks.find(b=>b.id===id);return `<div class="group-entry"><span>${esc(k?.name||'Block #'+id)} (#${id})${k?'':' · không có ở hướng này'}</span><button onclick="removeGroupBlockMember(${id})">✕</button></div>`;}).join('')}
   ${current&&!current.blockIds.length?'<div class="status">Biến thể chưa có Block. Chọn một Block ở Skeleton rồi dùng nút thêm bên dưới, hoặc kéo thả.</div>':''}
   <button ${current&&sel?.t==='k'?'':'disabled'} onclick="addSelectedBlockToGroup()">＋ Thêm Block đang chọn</button>
   <p class="status">None (chuỗi rỗng) sẽ ẩn toàn bộ Block đã gán cho Group, nhưng giữ nguyên Bone/Outfit/animation. Đổi biến thể được lưu trong JSON dự án và dùng làm mặc định khi xuất Unity JSON.</p>`;
 }
 host.innerHTML=html;
}
function addGroupBlock(){const name=($('groupNameInput')?.value||'').trim();if(!name)return alert('Nhập tên group mới.');if(groupNameTaken(name))return alert('Tên group đã tồn tại.');checkpointUndo();M.groupBlocks.push({name,defaultVariant:'',variants:[]});selectedGroupIndex=M.groupBlocks.length-1;renderGroupBlock();refreshSpriteVariantOptions();}
function renameGroupBlock(){const g=currentGroup(),name=($('groupNameInput')?.value||'').trim();if(!g||!name)return;if(groupNameTaken(name,selectedGroupIndex))return alert('Tên group đã tồn tại.');checkpointUndo();g.name=name;renderGroupBlock();refreshSpriteVariantOptions();}
function removeGroupBlock(){if(!currentGroup())return;checkpointUndo();M.groupBlocks.splice(selectedGroupIndex,1);selectedGroupIndex=Math.max(0,selectedGroupIndex-1);renderGroupBlock();draw();refreshSpriteVariantOptions();}
function selectGroupBlockVariant(name){const g=currentGroup();if(!g)return;if(name&&!g.variants.some(v=>v.name===name))return;checkpointUndo();g.defaultVariant=name;renderGroupBlock();renderList();draw();}
function addGroupBlockVariant(){const g=currentGroup(),name=($('groupVariantInput')?.value||'').trim();if(!g||!name)return alert('Nhập tên biến thể.');if(g.variants.some(v=>v.name.toLowerCase()===name.toLowerCase()))return alert('Tên biến thể đã tồn tại.');checkpointUndo();g.variants.push({name,blockIds:[]});g.defaultVariant=name;renderGroupBlock();renderList();draw();}
function renameGroupBlockVariant(){const g=currentGroup(),v=g?.variants.find(v=>v.name===g.defaultVariant),name=($('groupVariantInput')?.value||'').trim();if(!v||!name)return;if(g.variants.some(x=>x!==v&&x.name.toLowerCase()===name.toLowerCase()))return alert('Tên biến thể đã tồn tại.');checkpointUndo();v.name=name;g.defaultVariant=name;renderGroupBlock();draw();}
function removeGroupBlockVariant(){const g=currentGroup();if(!g||!g.defaultVariant)return;checkpointUndo();g.variants=g.variants.filter(v=>v.name!==g.defaultVariant);g.defaultVariant='';renderGroupBlock();renderList();draw();}
function addGroupBlockMember(id){const g=currentGroup(),v=g?.variants.find(v=>v.name===g.defaultVariant);if(!v)return alert('Chọn biến thể trước khi thêm Block.');if(!M.blocks.some(k=>k.id===id))return alert('Block không tồn tại ở hướng này.');for(const owner of M.groupBlocks)for(const variant of owner.variants)if(variant.blockIds.includes(id)){if(owner===g&&variant===v)return;return alert('Block #'+id+' đã nằm trong '+owner.name+' / '+variant.name+'. Bỏ liên kết cũ trước.');}checkpointUndo();v.blockIds.push(id);renderGroupBlock();renderList();draw();}
function removeGroupBlockMember(id){const g=currentGroup(),v=g?.variants.find(v=>v.name===g.defaultVariant);if(!v)return;checkpointUndo();v.blockIds=v.blockIds.filter(x=>x!==id);renderGroupBlock();renderList();draw();}
function addSelectedBlockToGroup(){if(sel?.t==='k')addGroupBlockMember(sel.id);}
function groupDragOver(e){e.preventDefault();e.currentTarget.classList.add('drag-target');e.dataTransfer.dropEffect='copy';}
function groupDragLeave(e){e.currentTarget.classList.remove('drag-target');}
function groupDropBlock(e){e.preventDefault();e.currentTarget.classList.remove('drag-target');const text=e.dataTransfer.getData('text/plain');const match=/^k:(\d+)$/.exec(text);const id=treeDragPayload?.type==='k'?treeDragPayload.id:(match?+match[1]:null);if(id!=null)addGroupBlockMember(+id);else alert('Hãy kéo một Block từ Skeleton.');}
function normalizeModel(m){
 m.groupBlocks=normalizeGroupBlocks(m.groupBlocks);
 m.nid=+m.nid||1;m.bones=Array.isArray(m.bones)?m.bones:[];m.blocks=Array.isArray(m.blocks)?m.blocks:[];m.dir=['down','up','left','right'].includes(m.dir)?m.dir:'down';
 let sets=Array.isArray(m.animationSets)?m.animationSets:[];
 if(!sets.length){const oldDirs=m.anims?normalizeDirs(m.anims):emptyDirections();if(m.anim&&!m.anims)oldDirs.down={fps:+m.anim.fps||12,frames:+m.anim.frames||24,keys:m.anim.keys||{}};sets=[{name:'Default',dirs:oldDirs}];}
 m.animationSets=sets.map((set,i)=>({name:String(set.name||('Animation '+(i+1))),dirs:normalizeDirs(set.dirs||set.anims||{}),unity:normalizeUnityMeta(set)}));
 if(!m.animationSets.length)m.animationSets=[{name:'Default',dirs:emptyDirections()}];
 m.activeAnimation=m.animationSets.some(a=>a.name===m.activeAnimation)?m.activeAnimation:m.animationSets[0].name;
 const baseRig={bones:cloneData(m.bones),blocks:cloneData(m.blocks)},saved=m.rigsByDir&&typeof m.rigsByDir==='object'?m.rigsByDir:{};
 m.rigsByDir={};
 for(const dir of ['down','up','left','right']){const rig=saved[dir]&&Array.isArray(saved[dir].bones)&&Array.isArray(saved[dir].blocks)?saved[dir]:baseRig;m.rigsByDir[dir]={bones:cloneData(rig.bones),blocks:cloneData(rig.blocks)};}
 const current=m.rigsByDir[m.dir];m.bones=cloneData(current.bones);m.blocks=cloneData(current.blocks);
 const active=m.animationSets.find(a=>a.name===m.activeAnimation);m.anims=active.dirs;m.anim=m.anims[m.dir];
 const normalizeBlocks=blocks=>blocks.forEach(k=>{k.b=Number.isFinite(+k.b)?+k.b:0;k.visible=k.visible!==false;k.demo=k.demo!==false;k.ox=+k.ox||0;k.sx=+k.sx||1;k.sy=+k.sy||1;k.ix=+k.ix||0;k.iy=+k.iy||0;k.ir=+k.ir||0;k.is=+k.is||1;k.z=+k.z||0;k.vis=['all','front','back'].includes(k.vis)?k.vis:'all';k.imgUp=k.imgUp||'';k.imgLeft=k.imgLeft||'';k.imgRight=k.imgRight||'';k.fx=+k.fx||0;k.x=Number.isFinite(+k.x)?+k.x:0;k.y=Number.isFinite(+k.y)?+k.y:0;k.a=+k.a||0;k.freeW=Math.max(4,+k.freeW||80);});
 Object.values(m.rigsByDir).forEach(r=>normalizeBlocks(r.blocks));return m;
}

function activeSet(){return M.animationSets.find(a=>a.name===M.activeAnimation)||M.animationSets[0]||null;}
function seedAnimationSet(set,bones=M.bones){
 if(!set)return;
 for(const dir of ['down','up','left','right']){
  const anim=set.dirs[dir]||(set.dirs[dir]=emptyAnim());
  for(const b of bones){
   const keys=anim.keys[b.id]||(anim.keys[b.id]={});
   if(!Object.keys(keys).length)keys[0]={x:b.x,y:b.y,a:b.a,l:b.l};
  }
 }
}
function refreshAnimationState(){
 if(!M.animationSets.length)M.animationSets=[{name:'Default',dirs:emptyDirections()}];
 if(!M.animationSets.some(a=>a.name===M.activeAnimation))M.activeAnimation=M.animationSets[0].name;
 const set=activeSet();M.anims=set.dirs;M.anim=M.anims[M.dir];
 $('timelineControls').hidden=false;$('noAnimationHint').hidden=true;
 $('deleteAnimationBtn').disabled=M.animationSets.length<=1;
 $('animationSelect').innerHTML=M.animationSets.map(a=>`<option value="${esc(a.name)}" ${a.name===M.activeAnimation?'selected':''}>${esc(a.name)}</option>`).join('');
 $('animationSelect').value=M.activeAnimation;$('directionSelect').value=M.dir;syncAnim();
}
const A=()=>{const set=activeSet();return set?set.dirs[M.dir]:(emptyAnim());};
const byId=id=>M.bones.find(b=>b.id==id),kids=id=>M.bones.filter(b=>b.p==id);
const desc=id=>kids(id).flatMap(b=>[b.id,...desc(b.id)]);
const cur=()=>sel&&(sel.t==='b'?byId(sel.id):M.blocks.find(k=>k.id==sel.id));
const esc=s=>String(s).replace(/[&<>"']/g,c=>'&#'+c.charCodeAt(0)+';');
const r2=v=>+(+v).toFixed(2);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const imageSrc=n=>imageData[n]||'';
const img=n=>{if(!n||!imageData[n])return null;if(!imageCache[n]){imageCache[n]=new Image();imageCache[n].src=imageData[n]}return imageCache[n].complete&&imageCache[n].naturalWidth?imageCache[n]:null};
/* Pose và tính toạ độ xương */
function pose(b,f){
 const keys=mode==='anim'&&A().keys[b.id],frames=keys?Object.keys(keys).map(Number).sort((a,b)=>a-b):[];
 if(!frames.length)return b;
 if(f<=frames[0])return keys[frames[0]];
 const lastFrame=frames.length-1;if(f>=frames[lastFrame])return keys[frames[lastFrame]];
 let i=0;while(frames[i+1]<f)i++;
 const p=keys[frames[i]],q=keys[frames[i+1]],t=(f-frames[i])/(frames[i+1]-frames[i]),mix=(a,b)=>a+(b-a)*t;
 return{x:mix(p.x,q.x),y:mix(p.y,q.y),a:mix(p.a,q.a),l:mix(p.l,q.l)};
}
function solve(){
 const world={};
 const go=b=>{
  if(world[b.id])return world[b.id];
  const q=pose(b,frame),parent=b.p&&byId(b.p),P=parent?go(parent):{tx:0,ty:0,wa:0};
  const c=Math.cos(P.wa*D),s=Math.sin(P.wa*D),hx=P.tx+q.x*c-q.y*s,hy=P.ty+q.x*s+q.y*c,wa=P.wa+q.a;
  return world[b.id]={hx,hy,wa,l:q.l,tx:hx+q.l*Math.cos(wa*D),ty:hy+q.l*Math.sin(wa*D)};
 };
 M.bones.forEach(go);return world;
}
function segs(world){
 const segments={};
 M.bones.forEach(b=>{
  const blocks=M.blocks.filter(k=>k.b==b.id).sort((a,b)=>a.s-b.s),stretch=world[b.id].l-b.l;
  const total=blocks.reduce((sum,k)=>sum+k.rank-1+.1,0)||1;let added=0;
  blocks.forEach(k=>{const base=(k.e-k.s)*b.l,extra=stretch*(k.rank-1+.1)/total;
   segments[k.id]={u:k.s*b.l+added,len:Math.max(0,base+extra),r0:base};added+=extra;
  });
 });return segments;
}
function blockKeyMap(anim=A()){
 if(!anim.blockKeys||typeof anim.blockKeys!=='object')anim.blockKeys={};
 return anim.blockKeys;
}
function blockStateAt(k,f=frame,dir=M.dir){
 const state={visible:k.visible!==false,image:imageForDirection(k,dir)};
 const keys=blockKeyMap(),frames=Object.keys(keys).map(Number).filter(n=>Number.isFinite(n)&&n<=f).sort((a,b)=>a-b);
 for(const keyFrame of frames){
  const items=keys[keyFrame]||[];
  const item=items.find(entry=>String(entry.blockId)===String(k.id));
  if(!item)continue;
  if(typeof item.visible==='boolean')state.visible=item.visible;
  if(typeof item.image==='string')state.image=item.image||imageForDirection(k,dir);
 }
 return state;
}
function animatedBlockImage(k,dir=M.dir,f=frame){return blockStateAt(k,f,dir).image;}
function blockVis(k){
 const state=blockStateAt(k,frame,M.dir);
 if(!state.visible)return false;
 if(k.vis==='front'&&M.dir==='up')return false;
 if(k.vis==='back'&&M.dir!=='up')return false;
 if(!groupBlockAllows(k.id))return false;
 return true;
}
function createBlockKeyframe(){
 if(!activeSet())return alert('Hãy tạo hoặc chọn animation trước.');
 if(!M.blocks.length)return alert('Model chưa có Block để tạo keyframe.');
 const f=String(clamp(Math.round(frame),0,A().frames)),map=blockKeyMap();
 if(!Array.isArray(map[f]))map[f]=[];
 if(!map[f].length)addBlockKeyItem(+f);
 renderProps();draw();
}
function addBlockKeyItem(f=Math.round(frame)){
 const map=blockKeyMap(),key=String(clamp(Math.round(f),0,A().frames));
 if(!Array.isArray(map[key]))map[key]=[];
 const used=new Set(map[key].map(item=>String(item.blockId)));
 const block=M.blocks.find(k=>!used.has(String(k.id)));
 if(!block)return alert('Các Block đều đã có trong keyframe này.');
 const previous=blockStateAt(block,+key-0.001,M.dir);
 map[key].push({blockId:block.id,visible:previous.visible,image:previous.image===imageForDirection(block,M.dir)?'':previous.image});
 renderProps();draw();
}
function updateBlockKeyItem(f,index,key,value){
 const map=blockKeyMap(),items=map[String(f)];
 if(!items||!items[index])return;
 const item=items[index];
 if(key==='blockId'){
  const block=M.blocks.find(k=>String(k.id)===String(value));if(!block)return;
  const duplicate=items.some((entry,i)=>i!==index&&String(entry.blockId)===String(block.id));
  if(duplicate)return alert('Block này đã có trong keyframe hiện tại.');
  const state=blockStateAt(block,+f-0.001,M.dir);
  item.blockId=block.id;item.visible=state.visible;
  item.image=state.image===imageForDirection(block,M.dir)?'':state.image;
 }else if(key==='visible')item.visible=!!value;
 else if(key==='image')item.image=String(value||'');
 renderProps();draw();
}
function removeBlockKeyItem(f,index){
 const map=blockKeyMap(),key=String(f),items=map[key];if(!items)return;
 items.splice(index,1);if(!items.length)delete map[key];
 renderProps();draw();
}
function renderBlockKeyframeProperties(){
 if(mode!=='anim'||!activeSet())return '';
 const f=String(clamp(Math.round(frame),0,A().frames)),items=blockKeyMap()[f]||[];
 const options=M.blocks.map(k=>`<option value="${k.id}">${esc(k.name)} (#${k.id})</option>`).join('');
 const imageOptions=block=>`<option value="">Ảnh gốc theo hướng (${esc(imageForDirection(block)||'chưa gán')})</option>`+LIB.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');
 const rows=items.map((item,index)=>{
  const block=M.blocks.find(k=>String(k.id)===String(item.blockId));
  if(!block)return `<div class="status">Block #${esc(item.blockId)} không còn tồn tại. <button onclick="removeBlockKeyItem(${f},${index})">Xóa mục</button></div>`;
  return `<div class="block-key-item">
   <div class="row"><label>Block cần thay đổi</label><select onchange="updateBlockKeyItem(${f},${index},'blockId',this.value)">${M.blocks.map(k=>`<option value="${k.id}" ${String(k.id)===String(item.blockId)?'selected':''}>${esc(k.name)} (#${k.id})</option>`).join('')}</select></div>
   <div class="row"><label>Hiển thị</label><input type="checkbox" ${item.visible!==false?'checked':''} onchange="updateBlockKeyItem(${f},${index},'visible',this.checked)"></div>
   <div class="row"><label>Ảnh thay thế</label><select onchange="updateBlockKeyItem(${f},${index},'image',this.value)">${imageOptions(block).replace(`value="${esc(item.image||'')}"`,`value="${esc(item.image||'')}" selected`)}</select></div>
   <button class="danger" onclick="removeBlockKeyItem(${f},${index})">✕ Xóa mục</button>
  </div>`;
 }).join('');
 return `<details class="block-key-panel" open>
  <summary>▣ BLOCK KEYFRAME · Frame ${f} <span class="status">(${items.length} Block)</span></summary>
  <div class="block-key-content">${rows||'<div class="status">Chưa có Block nào trong frame này.</div>'}
   <button onclick="addBlockKeyItem(${f})" ${M.blocks.length<=items.length?'disabled':''}>＋ Thêm Block</button>
   <p class="status">Chọn frame ở hàng ▣ BLOCK trên Timeline để mở/chỉnh keyframe. Icon vuông tím là Block Keyframe; hình thoi xanh là Bone Keyframe. Thay đổi ảnh và trạng thái sẽ giữ nguyên đến keyframe Block tiếp theo.</p>
  </div>
 </details>`;
}
function blockZ(k){const z=+k.z||0;return M.dir==='up'?-z:z;}
function setB(b,patch){
 if(mode==='rig'||!activeSet()){Object.assign(b,patch);return}
 const q=pose(b,frame);(A().keys[b.id]??={})[Math.round(frame)]={x:q.x,y:q.y,a:q.a,l:q.l,...patch};
}
function setTip(b,tx,ty,keepAngle){
 const W=solve(),w=W[b.id],parent=b.p&&W[b.p]?W[b.p].wa:0;
 const angle=Math.atan2(ty-w.hy,tx-w.hx)/D-parent,length=Math.hypot(tx-w.hx,ty-w.hy);
 setB(b,keepAngle?{a:angle}:{a:angle,l:length});
}
function setHead(b,hx,hy){
 const W=solve(),P=b.p&&W[b.p]?W[b.p]:{tx:0,ty:0,wa:0},c=Math.cos(-P.wa*D),s=Math.sin(-P.wa*D),dx=hx-P.tx,dy=hy-P.ty;
 setB(b,{x:dx*c-dy*s,y:dx*s+dy*c});
}
function worldToLocal(p,w){const dx=p.x-w.hx,dy=p.y-w.hy,c=Math.cos(w.wa*D),s=Math.sin(w.wa*D);return{x:dx*c+dy*s,y:-dx*s+dy*c}}
function localToWorld(x,y,w){const c=Math.cos(w.wa*D),s=Math.sin(w.wa*D);return{x:w.hx+x*c-y*s,y:w.hy+x*s+y*c}}
function parentDeltaToLocal(dx,dy,parentAngle){const c=Math.cos(-parentAngle*D),s=Math.sin(-parentAngle*D);return{x:dx*c-dy*s,y:dx*s+dy*c}}
function pointSegmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy;if(!len)return Math.hypot(p.x-a.x,p.y-a.y);const t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/len,0,1);return Math.hypot(p.x-(a.x+t*dx),p.y-(a.y+t*dy))}

/* Thêm, xoá và chọn đối tượng */
function addBone(){
 const parent=sel&&(sel.t==='b'?byId(sel.id):byId(cur()?.b));
 const b={id:M.nid++,name:'bone'+M.nid,p:parent?parent.id:0,x:0,y:0,a:parent?0:-90,l:100};
 M.bones.push(b);if(activeSet())seedAnimationSet(activeSet(),[b]);sel={t:'b',id:b.id};renderAll();
}
function addBlock(){
 // Block mới được tạo độc lập. Khi gắn vào xương, nó trở thành component của xương đó.
 const k={id:M.nid++,name:'block'+M.nid,b:0,x:0,y:0,a:0,freeW:80,s:0,e:1,h:40,oy:0,ox:0,rank:1,z:0,vis:'all',col:['#e57373','#64b5f6','#81c784','#ffd54f','#ba68c8'][M.nid%5],img:'',imgUp:'',demo:true,ir:0,is:1,ix:0,iy:0,fx:0,sx:1,sy:1};
 M.blocks.push(k);sel={t:'k',id:k.id};renderAll();
}
function del(){
 if(!sel)return;
 if(sel.t==='k')M.blocks=M.blocks.filter(k=>k.id!==sel.id);else removeBoneTree(sel.id);
 sel=ksel=null;renderAll();draw();
}
function pick(type,id){if(mode==='anim'&&type==='k')return;sel={t:type,id};ksel=null;renderAll();draw();}
function setTool(next){tool=next;['move','rotate','scale'].forEach(name=>$('tool'+name[0].toUpperCase()+name.slice(1)).classList.toggle('active',tool===name));draw();}
function renderAll(){renderList();renderProps();renderImageAssets();renderGroupBlock();}
function renderList(){
 const active=(type,id)=>sel&&sel.t===type&&sel.id===id?' s':'';
 const boneRows=[];
 const boneRow=(b,depth)=>{
  boneRows.push(`<div class="it tree-row${active('b',b.id)}" data-type="b" data-id="${b.id}" draggable="true" style="padding-left:${6+depth*12}px" onclick="pick('b',${b.id})" oncontextmenu="showContextMenu(event,'b',${b.id})" ondragstart="treeDragStart(event,'b',${b.id})" ondragover="treeDragOver(event)" ondragleave="treeDragLeave(event)" ondrop="treeDrop(event,'b',${b.id})"><span class="tree-label">🦴 ${esc(b.name)}</span></div>`);
  kids(b.id).forEach(child=>boneRow(child,depth+1));
 };
 M.bones.filter(b=>!b.p||!byId(b.p)).forEach(b=>boneRow(b,0));
 const blocks=[...M.blocks].sort((a,b)=>String(a.name).localeCompare(String(b.name))).map(k=>{
  const parent=byId(k.b),kind=parent?`<small>· Gắn vào ${esc(parent.name)}</small>`:'<small>· Block độc lập</small>';
  return `<div class="it tree-row ${parent?'component-row':'unattached'}${active('k',k.id)}" data-type="k" data-id="${k.id}" style="opacity:${blockVis(k)?1:.45}" onclick="pick('k',${k.id})" oncontextmenu="showContextMenu(event,'k',${k.id})" draggable="true" ondragstart="treeDragStart(event,'k',${k.id})"><input class="block-visibility" type="checkbox" title="Hiện/ẩn block" ${k.visible!==false?'checked':''} onclick="event.stopPropagation()" onchange="setBlockVisibility(${k.id},this.checked)"><span class="tree-label">▣ ${esc(k.name)} ${kind}</span></div>`;
 }).join('');
 $('list').innerHTML=`
<section class="tree-section">
    <h4 class="tree-section-title">
        <span>XƯƠNG (${M.bones.length})</span>
        <button onclick="addBone()">＋</button>
    </h4>
    ${boneRows.join('')||'<div class="status">Chưa có xương.</div>'}
</section>

<section class="tree-section block-section">
    <h4 class="tree-section-title">
        <span>BLOCK (${M.blocks.length})</span>
        <button onclick="addBlock()">＋</button>
    </h4>
    ${blocks||'<div class="status">Chưa có block.</div>'}
</section>`;
 $('list').oncontextmenu=e=>{if(e.target===$('list')||e.target.classList.contains('it'))showContextMenu(e,null,null)};
 $('mobilePaste').disabled=!objectClipboard;
}


function setBlockVisibility(id,visible){
 const block=M.blocks.find(k=>k.id===id);
 if(!block)return;
 block.visible=!!visible;
 renderList();
 draw();
}


/* Component attachment, hierarchy and VS Code-like tree actions */
function attachBlockToBone(block,boneId){
 if(!boneId){block.b=0;renderAll();return;}
 const bone=byId(boneId);if(!bone)return;
 // Một Bone có thể chứa nhiều Block độc lập; không xóa các Block đang gắn.
 block.b=boneId;block.s=0;block.e=1;block.rank=1;block.ox=0;block.sx=1;
 sel={t:'k',id:block.id};renderAll();draw();
}
function reparentBone(childId,parentId){
 const child=byId(childId),parent=parentId?byId(parentId):null;if(!child)return false;
 if(parent&&(parent.id===child.id||desc(child.id).includes(parent.id)))return false;
 const W=solve(),old=W[child.id],P=parent?W[parent.id]:{tx:0,ty:0,wa:0};
 const local=parentDeltaToLocal(old.hx-P.tx,old.hy-P.ty,P.wa);
 const current=pose(child,frame);child.p=parent?parent.id:0;
 setB(child,{x:local.x,y:local.y,a:old.wa-P.wa,l:current.l});
 renderAll();draw();return true;
}
function treeDragStart(e,type,id){treeDragPayload={type,id};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',type+':'+id);}
function treeDragOver(e){e.preventDefault();e.currentTarget.classList.add('drag-target');e.dataTransfer.dropEffect='move';}
function treeDragLeave(e){e.currentTarget.classList.remove('drag-target');}
function treeDrop(e,targetType,targetId){e.preventDefault();e.currentTarget.classList.remove('drag-target');const payload=treeDragPayload;treeDragPayload=null;if(!payload)return;if(mode==='anim'&&payload.type==='k')return;
 if(targetType==='b'&&payload.type==='b'){if(!reparentBone(payload.id,targetId))alert('Không thể đặt xương vào chính nó hoặc hậu duệ của nó.');}
 else if(targetType==='b'&&payload.type==='k'){const block=M.blocks.find(k=>k.id===payload.id);if(block)attachBlockToBone(block,targetId);}
}
function copyObject(cut=false){if(!sel)return;
 const o=cur();if(!o)return;
 if(sel.t==='k'){
  objectClipboard={type:'k',data:JSON.parse(JSON.stringify(o))};
  if(cut)M.blocks=M.blocks.filter(k=>k.id!==o.id);
 }else{
  const ids=[sel.id,...desc(sel.id)],set=new Set(ids);
  objectClipboard={type:'b',rootId:sel.id,bones:JSON.parse(JSON.stringify(M.bones.filter(b=>set.has(b.id)))),blocks:JSON.parse(JSON.stringify(M.blocks.filter(k=>set.has(k.b)))),keys:{}};
  Object.entries(M.anims).forEach(([dir,anim])=>{objectClipboard.keys[dir]={};ids.forEach(id=>{if(anim.keys[id])objectClipboard.keys[dir][id]=JSON.parse(JSON.stringify(anim.keys[id]));});});
  if(cut)removeBoneTree(sel.id);
 }
 if(cut)sel=null;renderAll();draw();
}
function removeBoneTree(id){const ids=[id,...desc(id)],set=new Set(ids);M.bones=M.bones.filter(b=>!set.has(b.id));M.blocks=M.blocks.filter(k=>!set.has(k.b));Object.values(M.animationSets||[]).forEach(set=>Object.values(set.dirs||{}).forEach(anim=>ids.forEach(key=>delete anim.keys[key])));Object.values(M.anims||{}).forEach(anim=>ids.forEach(key=>delete anim.keys[key]));}
function pasteObject(){if(!objectClipboard)return alert('Clipboard đang trống.');
 if(objectClipboard.type==='k'){
  const copy=JSON.parse(JSON.stringify(objectClipboard.data));copy.id=M.nid++;copy.name=copy.name+'_copy';copy.b=0;M.blocks.push(copy);sel={t:'k',id:copy.id};
 }else{
  const idMap=new Map();objectClipboard.bones.forEach(b=>idMap.set(b.id,M.nid++));
  const targetParent=sel&&sel.t==='b'?sel.id:0;
  objectClipboard.bones.forEach((source,index)=>{const b=JSON.parse(JSON.stringify(source));b.id=idMap.get(source.id);b.name=source.name+'_copy';b.p=idMap.has(source.p)?idMap.get(source.p):(source.id===objectClipboard.rootId?targetParent:0);M.bones.push(b);});
  objectClipboard.blocks.forEach(source=>{const k=JSON.parse(JSON.stringify(source));k.id=M.nid++;k.b=idMap.get(source.b)||0;k.name=k.name+'_copy';M.blocks.push(k);});
  Object.entries(objectClipboard.keys||{}).forEach(([dir,keys])=>Object.entries(keys).forEach(([oldId,frames])=>{const newId=idMap.get(+oldId);if(newId)M.anims[dir].keys[newId]=JSON.parse(JSON.stringify(frames));}));
  const root=objectClipboard.bones.find(b=>b.id===objectClipboard.rootId)||objectClipboard.bones[0];sel={t:'b',id:idMap.get(root.id)};
 }
 ksel=null;renderAll();draw();
}
function renameObject(){if(!sel)return;const o=cur();if(!o)return;const name=prompt('Tên mới:',o.name);if(name&&name.trim()){o.name=name.trim();renderAll();}}
function contextActionForSelection(){const r=$('list').getBoundingClientRect();showContextMenu({preventDefault(){},clientX:r.left+12,clientY:r.top+12},sel?.t||null,sel?.id??null);}
function showContextMenu(event,type,id){event.preventDefault?.();if(type&&id!=null){sel={t:type,id};ksel=null;renderAll();}
 const menu=$('treeContext'),has=!!sel,canPaste=!!objectClipboard;
 menu.innerHTML=`${has?'<button onclick="copyObject(false);hideContextMenu()">Copy</button><button onclick="copyObject(true);hideContextMenu()">Cut</button><button onclick="renameObject();hideContextMenu()">Rename</button>':''}<button onclick="pasteObject();hideContextMenu()" ${canPaste?'':'disabled'}>Paste</button><div class="separator"></div><button onclick="addBone();hideContextMenu()">＋ Thêm xương</button><button onclick="addBlock();hideContextMenu()">＋ Thêm block</button>${has?'<div class="separator"></div><button onclick="del();hideContextMenu()">Xóa</button>':''}`;
 const x=Math.min(event.clientX||window.innerWidth/2,window.innerWidth-190),y=Math.min(event.clientY||window.innerHeight/2,window.innerHeight-230);menu.style.left=Math.max(4,x)+'px';menu.style.top=Math.max(4,y)+'px';menu.style.display='block';
}
function hideContextMenu(){$('treeContext').style.display='none';}
window.addEventListener('pointerdown',e=>{if(!$('treeContext').contains(e.target))hideContextMenu();});
window.addEventListener('keydown',e=>{if(e.key==='Escape')hideContextMenu();});
function renderRigGuide(){
    return `
        <section class="guide">
            <h4>HƯỚNG DẪN RIG</h4>
            <p>Thêm xương:	Nhấn Thêm xương</p>
            <p>Thêm block:	Nhấn Thêm block</p>
            <p>Chọn xương/block:	Nhấn vào danh sách hoặc canvas</p>
            <p>Di chuyển xương:	Chọn Move, kéo xương</p>
            <p>Di chuyển đầu xương:	Kéo đầu xương</p>
            <p>Xoay xương:	Chọn Rotate, kéo vùng tam giác xương</p>
            <p>Thay đổi chiều dài:	Chọn Scale, kéo xương</p>
            <p>Di chuyển block:	Chọn Move, kéo block</p>
            <p>Xoay block:	Chọn Rotate, kéo block</p>
            <p>Thay đổi kích thước block:	Chọn Scale, kéo góc block</p>
            <p>Gắn block vào xương:	Kéo block lên xương hoặc chọn</p>
            <p>Tạo quan hệ cha/con:	Kéo xương vào xương khác</p>
            <p>Ẩn/hiện block:	Tick checkbox trước tên block</p>
            <p>Chỉnh thông số:	Chọn đối tượng, sửa Inspector</p>
        </section>
    `;
}

function renderAnimGuide(){
    return `
        <section class="guide">
            <h4>HƯỚNG DẪN ANIMATION</h4>
            <p>Tạo animation:	Nhập tên rồi nhấn Create</p>
            <p>Nhân bản animation:	Nhấn Duplicate</p>
            <p>Đổi tên:	Nhập tên rồi nhấn Rename</p>
            <p>Xóa animation:	Nhấn Delete	Xóa animation đang chọn</p>
            <p>Chọn hướng:	Down / Up / Left / Right</p>
            <p>Đặt keyframe:	Chọn xương, đến frame rồi nhấn Set Key</p>
            <p>Phát animation:	Nhấn Play</p>
            <p>Chỉnh FPS:	Sửa FPS</p>
            <p>Chỉnh số frame:	Sửa Frames</p>
            <p>Chọn frame:	Sửa Frame hoặc nhấn timeline</p>
            <p>Sao chép key:	Chọn key rồi Copy	Sao chép keyframe</p>
            <p>Cắt key:	Chọn key rồi Cut	Cắt keyframe</p>
            <p>Dán key:	Chọn frame rồi Paste</p>
            <p>Xóa key:	Chọn key rồi Delete</p>
            <p>Sao chép Down sang Up:	Nhấn Copy Down to Up</p>
        </section>
    `;
}
/* Inspector */
function renderProps(){
     const o = cur(), P = $('props');

    const guide = mode === 'rig'
        ? renderRigGuide()
        : renderAnimGuide();

    if(!o){
        P.innerHTML = guide +
            '<i>Chọn xương/block ở danh sách hoặc trên canvas</i>' +
            renderBlockKeyframeProperties();
        return;
    }

 const isBone=sel.t==='b',W=solve(),w=isBone&&W[o.id],q=isBone&&pose(o,frame);
 const field=(label,key,value,type='number',extra='')=>`<div class="row"><label>${label}</label><input type="${type}" ${extra} value="${esc(value)}" oninput="setP('${key}',this.value)"></div>`;
 let html=`<h4>${isBone?'XƯƠNG':'BLOCK'}${mode==='anim'&&isBone?' · key frame '+Math.round(frame):''}</h4>`+field('Tên','name',o.name,'text');
 if(isBone){
  html+=`<div class="row"><label>Xương cha</label><select onchange="setP('p',this.value)"><option value="0">— gốc —</option>${M.bones.filter(b=>b.id!==o.id&&!desc(o.id).includes(b.id)).map(b=>`<option value="${b.id}" ${b.id==o.p?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>`
   +field('X (local)','x',r2(q.x))+field('Y (local)','y',r2(q.y))+field('Góc (độ)','a',r2(q.a))+field('Độ dài','l',r2(q.l))
   +'<h4>Đầu mút xương (toạ độ thế giới)</h4>'+field('Tip X','tipx',r2(w.tx))+field('Tip Y','tipy',r2(w.ty));
 }else{
  html+=`<div class="row"><label>Component của</label><select onchange="setP('b',this.value)"><option value="0" ${!o.b?'selected':''}>— Block độc lập —</option>${M.bones.map(b=>`<option value="${b.id}" ${b.id==o.b?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>`
   +`<div class="row"><label>Demo (dùng ảnh)</label><input type="checkbox" ${o.demo!==false?'checked':''} onchange="setP('demo',this.checked)"></div>`
   +field('Lớp Z (độ sâu)','z',o.z||0,'number','step="1"')
   +`<div class="row"><label>Hiện ở hướng</label><select onchange="setP('vis',this.value)"><option value="all" ${o.vis==='all'?'selected':''}>Tất cả hướng</option><option value="front" ${o.vis==='front'?'selected':''}>Mặt trước (ẩn khi Up)</option><option value="back" ${o.vis==='back'?'selected':''}>Mặt sau (chỉ Up)</option></select></div>`
   +(o.b?`<div class="status">Block đang gắn vào xương. Kích thước và vị trí được tính theo xương.</div>`:field('Tọa độ X','x',o.x)+field('Tọa độ Y','y',o.y)+field('Góc block','a',o.a)+field('Rộng độc lập','freeW',o.freeW))+field('Thứ tự (1=chính)','rank',o.rank,'number','min="1" step="1"')+field('Từ (0-1)','s',o.s,'number','step="0.05"')+field('Đến (0-1)','e',o.e,'number','step="0.05"')
   +field('Dày','h',o.h)+field('Lệch X','ox',o.ox)+field('Lệch Y','oy',o.oy)+field('Màu tạm','col',o.col,'color')
   +'<h4>Ảnh theo hướng</h4>'
   +['down','up','left','right'].map(dir=>{const key=({down:'img',up:'imgUp',left:'imgLeft',right:'imgRight'})[dir],label=({down:'Down (mặt trước)',up:'Up (mặt sau)',left:'Left (trái)',right:'Right (phải)'})[dir];return `<div class="row"><label>${label}</label><button onclick="openLibraryForDirection('${dir}','${esc(o[key]||'')}')">Chọn ảnh</button><span style="color:var(--m);font-size:10px;max-width:90px;overflow:hidden;text-overflow:ellipsis">${esc(o[key]||'Chưa gán')}</span></div>`}).join('')
   +field('Xoay ảnh','ir',o.ir,'range','min="-180" max="180" step="1"')+field('Phóng ảnh','is',o.is,'range','min="0.05" max="5" step="0.01"')+field('Dời ảnh X','ix',o.ix)+field('Dời ảnh Y','iy',o.iy)
   +field('Rộng block','sx',o.sx,'number','min="0.05" step="0.05"')+field('Cao block','sy',o.sy,'number','min="0.05" step="0.05"')
   +`<div class="row"><label>Lật ngang ảnh</label><input type="checkbox" ${o.fx?'checked':''} onchange="setP('fx',this.checked?1:0)"></div>`
   +'<button onclick="fitImg()">Vừa khít block</button>';
 }
 P.innerHTML=html+renderBlockKeyframeProperties();
}
function setP(key,value){
 const o=cur();if(!o)return;
 if(key==='demo')value=!!value;
 else if(!STR.includes(key)&&key!=='tipx'&&key!=='tipy')value=+value||0;
 if(sel.t==='b'){
  if(['x','y','a','l'].includes(key))setB(o,{[key]:value});
  else if(key==='tipx'||key==='tipy'){const w=solve()[o.id];setTip(o,key==='tipx'?value:w.tx,key==='tipy'?value:w.ty,false)}
  else o[key]=value;
 }else{
  if(key==='b'){attachBlockToBone(o,+value||0);}
  else{o[key]=value;if(key==='rank')o.rank=Math.max(1,o.rank);if(key==='sx'||key==='sy')o[key]=Math.max(.05,o[key]);}
 }
 if(['name','p','b','z','vis','demo'].includes(key)){renderList();if(key!=='name')renderProps();}draw();
}
function imageFieldForDir(dir){return ({down:'img',up:'imgUp',left:'imgLeft',right:'imgRight'})[dir]||'img';}
function imageForDirection(k,dir=M.dir){return k?.[imageFieldForDir(dir)]||k?.img||'';}
function fitImg(){const k=cur(),name=k&&imageForDirection(k),image=name&&img(name),b=k&&byId(k.b);if(!image)return alert('Block chưa có ảnh');k.is=+Math.min((k.b?(k.e-k.s)*b.l:k.freeW)/image.naturalWidth,k.h/image.naturalHeight).toFixed(3);k.ix=k.iy=0;renderProps();}

/* Hình học block: sx/sy là co giãn bổ sung, ox là độ dời dọc xương */
function blockInfo(k,W,S){
 if(!k.b||!byId(k.b)){const w={hx:+k.x||0,hy:+k.y||0,wa:(+k.a||0)*D};return{w,s:{r0:Math.max(4,+k.freeW||80),len:Math.max(4,+k.freeW||80),u:0},xScale:k.sx||1,yScale:k.sy||1,width:Math.max(4,+k.freeW||80)*(k.sx||1),height:k.h*(k.sy||1),x0:-Math.max(4,+k.freeW||80)/2,cy:0,independent:true};}const w=W[k.b],s=S[k.id];if(!w||!s)return null;
 const xScale=(s.r0>0?s.len/s.r0:1)*(k.sx||1),yScale=k.sy||1;
 const width=s.r0*xScale,height=k.h*yScale,x0=s.u+(k.ox||0),cy=k.oy||0;
 return{w,s,xScale,yScale,width,height,x0,cy};
}
function blockHit(p,k,W,S){
 const info=blockInfo(k,W,S);if(!info||!info.width||!info.height)return false;
 const local=worldToLocal(p,info.w),u=(local.x-info.x0)/info.xScale,v=(local.y-info.cy)/info.yScale;
 return u>=0&&u<=info.s.r0&&Math.abs(v)<=k.h/2;
}
function cornerPoints(k,info){
 const x1=info.x0,x2=info.x0+info.width,y1=info.cy-info.height/2,y2=info.cy+info.height/2;
 return[
  {name:'tl',x:x1,y:y1},{name:'tr',x:x2,y:y1},{name:'bl',x:x1,y:y2},{name:'br',x:x2,y:y2}
 ].map(p=>({...p,world:localToWorld(p.x,p.y,info.w)}));
}
function nearestCorner(p,k,info,radius){
 return cornerPoints(k,info).map(c=>({...c,d:Math.hypot(p.x-c.world.x,p.y-c.world.y)})).filter(c=>c.d<radius).sort((a,b)=>a.d-b.d)[0]||null;
}

/* Animation có tên, mỗi animation có bốn hướng */
function saveActiveRig(){if(!M.rigsByDir)M.rigsByDir={};M.rigsByDir[M.dir]={bones:cloneData(M.bones),blocks:cloneData(M.blocks)};}
function syncRigDirectionTabs(){document.querySelectorAll('[data-rig-dir]').forEach(b=>b.classList.toggle('active',b.dataset.rigDir===M.dir));}
function setDir(direction){
 if(!['down','up','left','right'].includes(direction))return;
 if(direction!==M.dir){saveActiveRig();const rig=M.rigsByDir?.[direction];if(rig){M.bones=cloneData(rig.bones);M.blocks=cloneData(rig.blocks);}else M.rigsByDir[direction]={bones:cloneData(M.bones),blocks:cloneData(M.blocks)};}
 M.dir=direction;M.anims=activeSet()?.dirs||emptyDirections();M.anim=M.anims[direction];seedAnimationSet(activeSet(),M.bones);frame=clamp(frame,0,A().frames);ksel=null;syncAnim();$('directionSelect').value=direction;syncRigDirectionTabs();renderAll();draw();
}
function syncRigToAllDirections(){
 saveActiveRig();const source={bones:cloneData(M.bones),blocks:cloneData(M.blocks)};
 for(const dir of ['down','up','left','right'])M.rigsByDir[dir]={bones:cloneData(source.bones),blocks:cloneData(source.blocks)};
 for(const set of M.animationSets)seedAnimationSet(set,source.bones);
 syncRigDirectionTabs();renderAll();draw();
 alert('Đã đồng bộ cấu trúc xương và block từ hướng '+M.dir.toUpperCase()+' sang cả 4 hướng. Bạn có thể thay ảnh và chỉnh khớp riêng từng hướng.');
}
function nudgeSelection(dx,dy){
 if(!sel|| (mode==='anim'&&sel.t==='k'))return;
 if(sel.t==='b'){const w=solve()[sel.id];if(!w)return;setHead(byId(sel.id),w.hx+dx,w.hy+dy);}
 else{const k=cur();if(!k)return;if(!k.b){k.x=(+k.x||0)+dx;k.y=(+k.y||0)+dy;}else{const w=solve()[k.b];const local=parentDeltaToLocal(dx,dy,w?.wa||0);k.ox=(+k.ox||0)+local.x;k.oy=(+k.oy||0)+local.y;}}
 renderProps();draw();
}

function createAnimation(){
 const name=$('animationName').value.trim();if(!name)return alert('Nhập tên animation trước khi tạo.');
 if(M.animationSets.some(a=>a.name.toLowerCase()===name.toLowerCase()))return alert('Tên animation đã tồn tại.');
 const set={name,dirs:emptyDirections()};set.unity=normalizeUnityMeta(set);seedAnimationSet(set);M.animationSets.push(set);M.activeAnimation=name;M.anims=set.dirs;M.anim=set.dirs[M.dir];$('animationName').value='';frame=0;ksel=null;playing=false;$('pb').textContent='▶';refreshAnimationState();setMode('anim');renderAll();draw();
}
function duplicateAnimation(){
 const source=activeSet();
 if(!source)return alert('Hãy chọn animation cần nhân bản.');
 const base=source.name+'_copy';
 let name=base,suffix=2;
 while(M.animationSets.some(a=>a.name.toLowerCase()===name.toLowerCase())){
  name=base+suffix++;
 }
 const copy={name,dirs:cloneData(source.dirs)};
 M.animationSets.push(copy);
 M.activeAnimation=name;
 M.anims=copy.dirs;
 M.anim=copy.dirs[M.dir];
 $('animationName').value='';
 frame=0;ksel=null;playing=false;$('pb').textContent='▶';
 refreshAnimationState();
 setMode('anim');
 renderAll();
 draw();
}
function selectAnimation(name){
 // Không cho trạng thái bỏ chọn; luôn giữ animation hiện tại hoặc Default.
 if(!name||!M.animationSets.some(a=>a.name===name))name=M.activeAnimation||M.animationSets[0]?.name||'Default';
 if(!M.animationSets.some(a=>a.name===name)){M.animationSets.push({name:'Default',dirs:emptyDirections()});name='Default';}
 M.activeAnimation=name;M.anims=activeSet().dirs;M.anim=M.anims[M.dir];seedAnimationSet(activeSet());frame=0;ksel=null;playing=false;$('pb').textContent='▶';refreshAnimationState();setMode('anim');renderAll();draw();
}
function renameAnimation(){
 const set=activeSet();if(!set)return alert('Hãy chọn animation cần đổi tên.');
 const name=$('animationName').value.trim();
 if(!name)return alert('Nhập tên mới vào ô tên animation.');
 if(name.toLowerCase()!==set.name.toLowerCase()&&M.animationSets.some(a=>a!==set&&a.name.toLowerCase()===name.toLowerCase()))return alert('Tên animation đã tồn tại.');
 set.name=name;M.activeAnimation=name;M.anims=set.dirs;M.anim=set.dirs[M.dir];
 $('animationName').value='';refreshAnimationState();renderAll();draw();
}
function deleteAnimation(){
 const set=activeSet();if(!set)return;
 if(M.animationSets.length<=1)return alert('Phải giữ lại ít nhất một animation.');
 if(!confirm('Xoá animation "'+set.name+'"?'))return;
 M.animationSets=M.animationSets.filter(a=>a!==set);M.activeAnimation=M.animationSets[0].name;M.anims=activeSet().dirs;M.anim=M.anims[M.dir];frame=0;ksel=null;playing=false;$('pb').textContent='▶';refreshAnimationState();renderAll();draw();
}
function copyDownToUp(){
 if(!activeSet())return alert('Hãy tạo hoặc chọn animation trước.');
 const source=activeSet().dirs.down,target=activeSet().dirs.up;target.fps=source.fps;target.frames=source.frames;target.keys={};
 M.bones.forEach(b=>{const keys=source.keys[b.id];if(!keys)return;target.keys[b.id]={};Object.keys(keys).forEach(f=>{const pose=keys[f],deltaLength=pose.l-b.l,deltaX=pose.x-b.x;target.keys[b.id][f]={x:b.p?b.x-deltaX:pose.x,y:pose.y,a:-pose.a,l:Math.max(4,b.l-deltaLength)}})});
 setDir('up');setMode('anim');
}
