function updateCropBox(){$('cropBox').style.left=cropRect.x+'px';$('cropBox').style.top=cropRect.y+'px';$('cropBox').style.width=cropRect.w+'px';$('cropBox').style.height=cropRect.h+'px';syncCropDimensions();updateCropGridOverlay();}
function updateCropGridOverlay(){const overlay=$('cropGridOverlay'),stage=$('cropStage');if(!overlay||!stage)return;const gx=clamp(Math.round(+$('cropGridX').value||1),1,128),gy=clamp(Math.round(+$('cropGridY').value||1),1,128);overlay.classList.toggle('active',cropGridEnabled);overlay.style.setProperty('--grid-x',(stage.clientWidth/gx)+'px');overlay.style.setProperty('--grid-y',(stage.clientHeight/gy)+'px');const info=$('cropGridInfo');if(info&&cropNatural.w>1)info.textContent=`Ô lưới: ${Math.round(cropNatural.w/gx)} × ${Math.round(cropNatural.h/gy)} px · Khung cắt sẽ hít theo lưới.`;}
function snapCropToGrid(){if(!cropGridEnabled)return;const stage=$('cropStage'),gx=clamp(Math.round(+$('cropGridX').value||1),1,128),gy=clamp(Math.round(+$('cropGridY').value||1),1,128),cw=stage.clientWidth/gx,ch=stage.clientHeight/gy;if(!cw||!ch)return;let l=Math.round(cropRect.x/cw)*cw,t=Math.round(cropRect.y/ch)*ch,r=Math.round((cropRect.x+cropRect.w)/cw)*cw,b=Math.round((cropRect.y+cropRect.h)/ch)*ch;l=clamp(l,0,stage.clientWidth-cw);t=clamp(t,0,stage.clientHeight-ch);r=clamp(r,l+cw,stage.clientWidth);b=clamp(b,t+ch,stage.clientHeight);cropRect={x:l,y:t,w:r-l,h:b-t};}
